files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f9f9f9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #1a5fbf;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #1a5fbf;
  --vt-accent-on-deep: #6ba6ff;
  --vt-line: #eaeaea;
  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink);
  background-color: var(--vt-surface);
  position: relative;
  padding-top: 94px;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 20px 0;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  text-decoration: none;
  color: var(--vt-accent-ink);
  font-size: 24px;
  font-weight: 700;
  margin: 0 30px;
  padding: 0;
  text-align: center;
}

.brand {
  display: inline-block;
}

.navLinks {
  display: flex;
  gap: 30px;
  align-items: center;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  padding: 15px 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent-ink);
  outline-offset: 2px;
}

.hero {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.heroImage {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  z-index: 2;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

.kicker {
  color: var(--vt-accent-ink);
  font-weight: 600;
  margin-bottom: 0.5rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.heroTitle {
  font-size: 48px;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--vt-ink);
}

.heroWord {
  color: var(--vt-accent-ink);
  display: block;
}

.heroIntro {
  color: var(--vt-ink-soft);
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.cta {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent-ink);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  text-decoration: none;
  transition: all 0.3s;
  background: transparent;
}

.cta:hover {
  background: var(--vt-line);
}

.contactPhone {
  color: var(--vt-ink);
  font-weight: 600;
  margin: 0;
}

.phoneIcon {
  font-style: normal;
  margin-right: 0.5rem;
}

.phoneIcon::before {
  content: "\260E";
}

.sectionPadding {
  padding: 7rem 0;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.aboutText {
  width: 100%;
}

.aboutTitle {
  font-size: 36px;
  margin-bottom: 1.5rem;
  color: var(--vt-ink);
}

.aboutText p {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}

.gallery {
  background: var(--vt-surface);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 1 1 50%;
  padding: 0;
}

.galleryItem img {
  width: 100%;
  height: auto;
  display: block;
}

.timelineSection {
  background: var(--vt-surface-2);
}

.timelineTitle {
  text-align: center;
  font-size: 36px;
  margin-bottom: 3rem;
  color: var(--vt-ink);
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNode {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-around;
  margin: 2rem 0;
}

.timelineContent {
  width: 45%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 0;
  border-radius: 0 0 0.25rem 0.25rem;
}

.timelineNodeTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
  color: var(--vt-ink-soft);
}

.timelineIcon {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  position: relative;
}

.timelineIcon span {
  color: var(--vt-accent-ink);
  font-size: 2rem;
  font-weight: 700;
}

.timelineDate {
  width: 30%;
  padding: 1rem 0;
  color: var(--vt-ink-soft);
}

.timelineNode.odd .timelineContent {
  order: 1;
}

.timelineNode.odd .timelineIcon {
  order: 2;
}

.timelineNode.odd .timelineDate {
  order: 3;
  text-align: left;
}

.timelineNode.even .timelineContent {
  order: 3;
}

.timelineNode.even .timelineIcon {
  order: 2;
}

.timelineNode.even .timelineDate {
  order: 1;
  text-align: right;
}

.timelineNode.odd .timelineContent h3,
.timelineNode.odd .timelineContent p {
  text-align: right;
}

.timelineNode.even .timelineContent h3,
.timelineNode.even .timelineContent p {
  text-align: left;
}

.siteFooter {
  background: var(--vt-surface-2);
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerCol {
  flex: 1;
  min-width: 200px;
}

.footerTitle {
  font-size: 24px;
  margin-bottom: 1.5rem;
  color: var(--vt-ink);
}

.footerCol p {
  color: var(--vt-ink-soft);
  margin-bottom: 0.5rem;
}

.footerCol a {
  color: var(--vt-accent-ink);
  text-decoration: none;
}

.footerCol a:hover {
  color: var(--vt-ink);
}

.socialLinks {
  list-style: none;
  padding: 0;
  display: flex;
  gap: 1rem;
}

.copyrightText {
  font-size: 14px;
  color: var(--vt-ink-soft);
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .hero {
    height: inherit;
    min-height: auto;
  }

  .heroText {
    position: relative;
    width: auto;
    margin: -100px 15px 0;
    padding: 2rem;
    bottom: auto;
    right: auto;
    z-index: 1;
  }

  .timeline::before {
    left: 33px;
    top: 60px;
    height: 90%;
    transform: none;
  }

  .timelineNode {
    flex-direction: column;
    align-items: flex-start;
  }

  .timelineContent {
    width: 100%;
    order: 3 !important;
  }

  .timelineIcon {
    order: 1 !important;
    position: absolute;
    left: 0;
    top: 60px;
    width: 70px;
    height: 70px;
  }

  .timelineIcon span {
    font-size: 1.5rem;
  }

  .timelineDate {
    order: 2 !important;
    width: 100%;
    text-align: left !important;
    padding-left: 100px;
  }

  .timelineNode.odd .timelineContent h3,
  .timelineNode.odd .timelineContent p,
  .timelineNode.even .timelineContent h3,
  .timelineNode.even .timelineContent p {
    text-align: left;
  }
}

@media screen and (max-width: 767px) {
  .heroTitle {
    font-size: 38px;
  }

  .aboutTitle,
  .timelineTitle {
    font-size: 32px;
  }

  .sectionPadding {
    padding: 5rem 0;
  }

  .nav {
    padding: 10px 0;
  }

  .navLinks a {
    padding: 5px 0;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .cta {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}
